#!/usr/bin/env python3
"""Stdlib-only calculators for the design's pre-registration.
NO data is used here: every number below is an ILLUSTRATIVE hypothetical input.
Purpose: (1) exact McNemar rejection threshold / minimum detectable discordance,
(2) required number of discordant gold instances for 80% power,
(3) implied human-gold size given an assumed disagreement rate,
(4) gold-annotation budget for a target macro-F1 precision.
"""
from math import comb, ceil, sqrt
from statistics import NormalDist

Z = NormalDist().inv_cdf(0.975)  # 1.959963985

def mcnemar_exact_p(b, a):
    """Two-sided exact McNemar p-value for discordant cells (a: raw right/Docta wrong,
    b: Docta right/ raw wrong). Null: each discordant pair is 50/50."""
    n = a + b
    k = min(a, b)
    tail = sum(comb(n, i) for i in range(k + 1)) / (2 ** n)
    return min(1.0, 2.0 * tail)

def crit_b(n, alpha=0.05):
    """Smallest b (> n/2) that rejects at alpha, given n discordant pairs."""
    for b in range(n // 2 + 1, n + 1):
        if mcnemar_exact_p(b, n - b) < alpha:
            return b
    return None

def power_fixed_n(n, theta, alpha=0.05):
    """Power when a fraction theta of discordant pairs favour Docta."""
    bc = crit_b(n, alpha)
    if bc is None:
        return 0.0
    return sum(comb(n, i) * theta ** i * (1 - theta) ** (n - i)
               for i in range(bc, n + 1))

def min_n_disc(theta, alpha=0.05, target=0.80):
    n = 2
    while n <= 4000:
        if power_fixed_n(n, theta, alpha) >= target:
            return n
        n += 1
    return None

print("== exact McNemar: minimum b out of n discordant pairs needed for p<0.05 ==")
for n in (20, 30, 40, 50, 80, 100, 150, 200, 300, 500):
    bc = crit_b(n)
    print(f"  n={n:4d} -> b>={bc:3d} (a={n-bc:3d})  delta_acc_on_D>={((bc-(n-bc))/n):.3f}")

print("\n== minimum #discordant gold pairs for 80% power (two-sided a=0.05) ==")
for theta in (0.55, 0.60, 0.65, 0.70, 0.75, 0.80):
    nd = min_n_disc(theta)
    print(f"  theta={theta:.2f} -> n_disc={nd}")

print("\n== implied human-gold size for D, given hypothetical disagreement rate rho ==")
for theta in (0.60, 0.65, 0.70):
    nd = min_n_disc(theta)
    row = []
    for rho in (0.05, 0.10, 0.20, 0.30):
        row.append(f"rho={rho:.2f}: N_gold={ceil(nd/rho)}")
    print(f"  theta={theta:.2f} n_disc={nd:5d} | " + " | ".join(row))

def n_per_class(moe, p=0.75, k=1, design=1.0):
    return ceil(design * (Z ** 2) * p * (1 - p) / moe ** 2)

print("\n== gold-annotation budget for per-class F1 precision (illustrative p=0.75) ==")
for moe in (0.05, 0.03, 0.02):
    n1 = n_per_class(moe)
    print(f"  +/-{moe*100:.0f}pp: n_per_class={n1:5d}  k=5 classes -> ~{n1*5} gold instances"
          f"  k=10 -> ~{n1*10}")

print("\n== instrument-sensitivity check: detect a KNOWN injected noise drop of d pp on D ==")
for d in (0.05, 0.10, 0.15, 0.20):
    for nD in (200, 400, 800):
        # noise injected so that d*nD pairs flip from correct to wrong, all in one direction
        b, a = int((1 - d) * nD / 2), int((1 + d) * nD / 2)
        print(f"  d={d:.2f} nD={nD:4d}: paired exact McNemar p={mcnemar_exact_p(b,a):.2e}")
